828	  async pedidosDisponiveis(motoboyId: number, restaurantId: number) {
829	    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
830	    await this.exigirUsaMotoboy(restaurantId);
831	
832	    const { data, error } = await this.supabase.client
833	      .from('orders')
834	      .select('id, total, status, payment_method, created_at, customer_id')
835	      .eq('restaurant_id', restaurantId)
836	      .eq('status', 'ready')
837	      .is('motoboy_id', null)
838	      .order('created_at', { ascending: true });
839	    if (error) throw error;
