860	  async pegarPedido(pedidoId: number, motoboyId: number) {
861	    const { data: pedido } = await this.supabase.client
862	      .from('orders')
863	      .select('id, restaurant_id')
864	      .eq('id', pedidoId)
865	      .maybeSingle();
866	    if (!pedido) throw new NotFoundException('Pedido não encontrado');
867	    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
868	    await this.exigirUsaMotoboy(pedido.restaurant_id);
869	
870	    const { data, error } = await this.supabase.client
871	      .from('orders')
872	      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
873	      .eq('id', pedidoId)
874	      .eq('restaurant_id', pedido.restaurant_id)
875	      .eq('status', 'ready')
876	      .is('motoboy_id', null)
877	      .select('id');
878	    if (error) throw error;
879	    if (!data || data.length === 0) {
880	      throw new ConflictException('Pedido já foi pego por outro motoboy ou não está disponível');
881	    }
882	    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
883	  }
884	
885	  async reivindicarPedido(pedidoId: number, motoboyId: number) {
886	    const { data: pedido } = await this.supabase.client
887	      .from('orders')
888	      .select('id, restaurant_id')
889	      .eq('id', pedidoId)
890	      .maybeSingle();
891	    if (!pedido) throw new NotFoundException('Pedido não encontrado');
892	    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
893	    await this.exigirUsaMotoboy(pedido.restaurant_id);
894	
895	    const { data, error } = await this.supabase.client
896	      .from('orders')
897	      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
898	      .eq('id', pedidoId)
899	      .eq('restaurant_id', pedido.restaurant_id)
900	      .in('status', ['ready', 'preparing', 'confirmed'])
901	      .is('motoboy_id', null)
902	      .select('id');
903	    if (error) throw error;
904	    if (!data || data.length === 0) {
905	      throw new ConflictException('Pedido não encontrado, já foi atribuído ou não está disponível');
906	    }
907	    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
908	  }
